      const backend = MacOsSandboxBackend();
      expect(
        backend.buildProfile(spec(networkAllowed: false), workspaceRoot: '/x'),
        backend.buildSandboxProfile(
          spec(networkAllowed: false),
          workspaceRoot: '/x',
        ),
      );
    });

