      'a workspace-only spec (L1 shape) confines writes and sensitive reads',
      () {
        final profile = MacOsSandboxBackend().buildSandboxProfile(
          const CubeSpec(
            name: 'l1-core',
            filesystem: CubeFsPolicy(workspace: '/Users/agent/proj'),
          ),
