CubeSpec spec({required bool networkAllowed}) => CubeSpec(
  name: 'test-cube',
  tools: const CubeToolPolicy(allow: {'git'}),
  network: networkAllowed
      ? const CubeNetworkPolicy(allow: [CubeNetworkRule(host: '*')])
