      final profile = MacOsSandboxBackend().buildSandboxProfile(
        CubeSpec(
          name: 'test-cube',
          filesystem: const CubeFsPolicy(
            mounts: [
              CubeMount(path: '/etc/hosts', access: CubePathAccess.deny),
