messages.preview:
/// macOS sandbox-exec backend: generates an SBPL profile from a cube spec
/// and wraps commands in `sandbox-exec -f <profile>`.
///
/// The generated policy mirrors [CubeSpec]: the workspace is writ…

blocks.text:
/// macOS sandbox-exec backend: generates an SBPL profile from a cube spec
/// and wraps commands in `sandbox-exec -f <profile>`.
///
/// The generated policy mirrors [CubeSpec]: the workspace is writable,
/// `ro` mounts are readable but not writable, `deny` mounts vanish, and
/// the network is fully denied unless the spec allows it. Unless a mount
/// grants root-level access, writes outside the workspace and `rw` mounts
/// are denied blanket-wide (`2>/dev/null` and the stdio fd aliases stay
/// writable), and specs that do not grant root reads get a curated read
/// deny set (system config, user homes). The wrapped command runs under
/// `/usr/bin/env -i` — the clean-environment ceiling: inherited host
/// variables are gone, only the PATH/HOME/TMPDIR trio plus the cube's
/// injected vars are present.
library;

import '../config/cube_spec.dart';
import '../config/fs_policy.dart';
import 'cube_backend.dart';

/// The macOS backend: SBPL profile generation plus `sandbox-exec` wrapping.
final class MacOsSandboxBackend
    implements CubeSandboxBackend, CubeProfileStaging {
  /// Creates the backend bound to a run's context. The defaults exist for
  /// bare display/backends-picked-outside-a-run; kernel execution always
  /// passes the real workspace, tmpdir and injected env.
  const MacOsSandboxBackend({
    this.workspaceRoot = '/workspace',
    this.tmpdir = '/tmp',
    this.envVars = const {},
  });

  /// The real writable root (the env cwd) — `HOME` inside the sandbox.
  final String workspaceRoot;

  /// Writable scratch directory handed to the child as `TMPDIR`.
  final String tmpdir;

  /// The cube's injected environment variables (hidden vars excluded).
  final Map<String, String> envVars;

  @override
  bool get enforces => true;

  @override
  String wrapCommand(
    String command, {
    required String profilePath,
    Map<String, String> env = const {},
  }) {
    final prefix = cubeEnvPrefix(
      workspaceRoot: workspaceRoot,
      tmpdir: tmpdir,
      envVars: {...envVars, ...env},
    );
    return 'sandbox-exec -f ${shellQuote(profilePath)} '
        '/usr/bin/env -i $prefix /bin/bash -c ${shellQuote(command)}';
  }

  @override
  String buildProfile(CubeSpec spec, {required String workspaceRoot}) =>
      buildSandboxProfile(spec, workspaceRoot: workspaceRoot);

  @override
  String describe() =>
      'macOS sandbox-exec (SBPL profile + clean env -i; kernel enforcement '
      'active in backend: kernel mode)';

  /// Renders [spec] as an SBPL profile.
  ///
  /// [workspaceRoot] overrides the spec's workspace as the writable subpath
  /// (the CLI passes the real process cwd; the cube's `/workspace` is
  /// realized as the env cwd).
  ///
  /// The kernel matches SBPL patterns against the RESOLVED path: macOS
  /// firmware symlinks (`/etc`, `/tmp`, `/var` → `/private/...`) make a
  /// symlink-form pattern silently match nothing, so every confined path is
  /// emitted in BOTH forms. The shape stays allow-default + explicit denies
  /// — a catch-all `(deny file-read*)` aborts exec — and per-path rules
  /// always use `file-read*`/`file-write*` with `subpath` (the
  /// `file-read-data`/`literal` single-file forms do not hold).
  String buildSandboxProfile(CubeSpec spec, {String? workspaceRoot}) {
    final workspace = workspaceRoot ?? spec.filesystem.workspace;
    final mounts = spec.filesystem.mounts;
    final buffer = StringBuffer('(version 1)\n(allow default)\n');
    if (!mounts.any(_rootWritesEverywhere)) _denyBlanketWrites(buffer);
    if (!mounts.any(_rootReadsEverywhere)) {
      _curatedReadDenies(buffer, workspace);
    }
    _allowWorkspaceWrites(buffer, workspace);
    for (final mount in mounts) {
      _mountRules(buffer, mount);
    }
    buffer.writeln(
      spec.network.allowsAnyNetwork ? '(allow network*)' : '(deny network*)',
    );
    return buffer.toString();
  }
}

/// Whether a root-level mount makes reads broad by design (L2's `ro /`
/// reads everywhere).
bool _rootReadsEverywhere(CubeMount mount) =>
    mount.path == '/' && mount.access != CubePathAccess.deny;

/// Whether a root-level mount makes writes broad by design (L3's `rw /`
/// writes everywhere).
bool _rootWritesEverywhere(CubeMount mount) =>
    mount.path == '/' && mount.access == CubePathAccess.readWrite;

/// The blanket write deny for profiles without a root-level `rw` mount,
/// with the persistence-free sinks kept writable: `2>/dev/null` and the
/// stdio fd aliases must keep working inside the sandbox.
void _denyBlanketWrites(StringBuffer buffer) {
  buffer.writeln('(deny file-write*)');
  buffer
    ..writeln('(allow file-write* (subpath "/dev/null"))')
    ..writeln('(allow file-write* (subpath "/dev/fd"))');
}

/// The curated read confinement for profiles without a root-level read:
/// deny the high-value disclosure targets (system config, every user home)
/// while keeping exec viable — a blanket `(deny file-read*)` aborts exec,
/// since the payload and dyld must read /bin/bash and /usr/lib/….
/// The workspace may live under /Users: re-allow it over the deny.
void _curatedReadDenies(StringBuffer buffer, String workspace) {
  for (final path in [
    ..._resolvedVariants('/etc'),
    ..._resolvedVariants('/Users'),
  ]) {
    buffer.writeln('(deny file-read* (subpath "$path"))');
  }
  for (final path in _resolvedVariants(workspace)) {
    buffer.writeln('(allow file-read* (subpath "$path"))');
  }
}

/// The workspace write allows (the default-allow profile needs the
/// explicit subpath form over the blanket deny).
void _allowWorkspaceWrites(StringBuffer buffer, String workspace) {
  for (final path in _resolvedVariants(workspace)) {
    buffer.writeln('(allow file-write* (subpath "$path"))');
  }
}

/// Per-mount SBPL rules, emitted in both resolved spellings.
///
/// P1 (ordering): within an operation class (`file-read*`/`file-write*`) the
/// kernel applies the LAST matching rule — not the most specific one
/// (observed on l1-dev: the curated `(deny file-read* (subpath "/Users"))`
/// beat subpath allows until a LATER allow re-allowed the path; Apple's
/// shipped docs do not cover conflict resolution — sandbox(7) documents the
/// facility only — so this ordering is pinned empirically by the profile
/// tests and the live macOS legs). Rule order is therefore load-bearing:
/// these mount rules are emitted AFTER `_curatedReadDenies` so an `ro`/`rw`
/// mount under a denied prefix re-allows it, and within a mount list the
/// later entry wins per class — the ro+rw twin mounts in l1-dev rely on
/// exactly that.
///
/// A `readWrite` mount is read-write in the kernel as in the Dart guard: it
/// emits BOTH allows. Emitting only the write allow made rw mounts kernel-
/// unreadable under a read-denied prefix while the Dart fs guard kept
/// granting reads — file tools passed, wrapped shells got `Operation not
/// permitted` (issue #709).
void _mountRules(StringBuffer buffer, CubeMount mount) {
  for (final path in _resolvedVariants(mount.path)) {
    switch (mount.access) {
      case CubePathAccess.readOnly:
        buffer
          ..writeln('(allow file-read* (subpath "$path"))')
          ..writeln('(deny file-write* (subpath "$path"))');
      case CubePathAccess.deny:
        buffer
          ..writeln('(deny file-read* (subpath "$path"))')
          ..writeln('(deny file-write* (subpath "$path"))');
      case CubePathAccess.readWrite:
        buffer
          ..writeln('(allow file-read* (subpath "$path"))')
          ..writeln('(allow file-write* (subpath "$path"))');
    }
  }
}

/// Both SBPL spellings for [path]: itself plus the `/private`-resolved form
/// when it lives under one of the firmware symlink roots. An already
/// canonical path maps to itself only.
///
/// P2 (literal-path matching + symlink-node traversal): SBPL filters match
/// the LITERAL path of an operation. Opening `/etc/ssl/cert.pem` must first
/// read the `/etc` symlink NODE, and a subpath filter on `/etc/ssl` does not
/// match that node — only the `/private/etc/...` spelling bypasses the
/// symlink entirely. These variants therefore cover the firmware-symlink
/// TARGETS, but they cannot and do not cover the sy…

messages.preview:
/// Live macOS kernel-mode confinement check for an L1-shaped cube: under
/// `sandbox-exec` the payload cannot read `/etc/hosts`, cannot
/// redirect-write above the workspace, and can write inside t…

blocks.text:
/// Live macOS kernel-mode confinement check for an L1-shaped cube: under
/// `sandbox-exec` the payload cannot read `/etc/hosts`, cannot
/// redirect-write above the workspace, and can write inside the workspace
/// and to `/dev/null`.
///
/// Skipped everywhere `sandbox-exec` is unavailable (Linux CI containers);
/// validated on a real macOS host with:
///
/// ```sh
/// dart test test/cube/backends/macos_sandbox_live_test.dart
/// ```
library;

import 'dart:io';

import 'package:flutter_agent_harness/src/cube/backends/cube_backend.dart';
import 'package:flutter_agent_harness/src/cube/backends/macos_sandbox.dart';
import 'package:flutter_agent_harness/src/cube/config/cube_spec.dart';
import 'package:flutter_agent_harness/src/cube/config/fs_policy.dart';
import 'package:flutter_agent_harness/src/cube/config/tool_policy.dart';
import 'package:test/test.dart';

/// Whether live kernel enforcement can run on this host.
final bool _liveMacOs =
    Platform.isMacOS &&
    Process.runSync('which', ['sandbox-exec']).exitCode == 0;

/// Whether the HOST itself already sandboxes reads (e.g. an fa cube
/// session): nested sandbox profiles intersect, so the profile under test
/// cannot re-allow what the outer profile denies — the live legs need a
/// clean host (CI macOS leg or a developer machine).
final bool _hostAlreadySandboxed = () {
  try {
    File('/etc/hosts').readAsStringSync();
    return false;
  } catch (_) {
    return true;
  }
}();

void main() {
  group(
    'macOS kernel mode live',
    () {
      late Directory workspace;
      late String profilePath;

      setUp(() {
        workspace = Directory.systemTemp.createTempSync('fah-cube-live-');
        final spec = CubeSpec(
          name: 'l1-core',
          backend: CubeBackendMode.kernel,
          tools: const CubeToolPolicy(allow: {'echo', 'cat'}),
          filesystem: CubeFsPolicy(workspace: workspace.path),
        );
        profilePath = '${workspace.path}/.fah/cube-profiles/live.sb';
        Directory(
          '${workspace.path}/.fah/cube-profiles',
        ).createSync(recursive: true);
        File(profilePath).writeAsStringSync(
          const MacOsSandboxBackend().buildSandboxProfile(
            spec,
            workspaceRoot: workspace.path,
          ),
        );
      });

      tearDown(() {
        workspace.deleteSync(recursive: true);
      });

      /// Runs [command] inside the staged sandbox with the workspace as cwd.
      Future<ProcessResult> run(String command) => Process.run('/bin/sh', [
        '-c',
        'cd ${shellQuote(workspace.path)} && '
            '${const MacOsSandboxBackend().wrapCommand(command, profilePath: profilePath)}',
      ]);

      test('a redirect above the workspace fails', () async {
        final escape = '${workspace.parent.path}/fah-cube-escape.txt';
        final result = await run('echo x > ${shellQuote(escape)}');
        expect(result.exitCode, isNot(0));
        expect(File(escape).existsSync(), isFalse);
      });

      test('a redirect inside the workspace succeeds', () async {
        final result = await run('echo x > out.txt');
        expect(result.exitCode, 0, reason: result.stderr.toString());
        expect(File('${workspace.path}/out.txt').existsSync(), isTrue);
      });

      test('reading /etc/hosts fails', () async {
        final result = await run('cat /etc/hosts');
        expect(result.exitCode, isNot(0));
        expect(result.stdout, isEmpty);
      });

      test('writing /dev/null succeeds', () async {
        final result = await run('echo x > /dev/null');
        expect(result.exitCode, 0, reason: result.stderr.toString());
      });
    },
    skip: !_liveMacOs
        ? 'live macOS kernel mode: sandbox-exec not on this host'
        : _hostAlreadySandboxed
        ? 'live macOS kernel mode: host is itself sandboxed (nested '
              'sandbox profiles intersect — an inner allow cannot lift an '
              'outer deny)'
        : false,
  );
}

messages.preview:
/// Filesystem policy for a cube (`spec.filesystem:`): which paths a sandboxed
/// run may read or write.
///
/// ```yaml
/// spec:
///   filesystem:
///     workspace: /workspace      # optional, def…

blocks.text:
/// Filesystem policy for a cube (`spec.filesystem:`): which paths a sandboxed
/// run may read or write.
///
/// ```yaml
/// spec:
///   filesystem:
///     workspace: /workspace      # optional, default /workspace
///     mounts:
///       - {path: /usr/bin, access: ro}   # access: ro | rw | deny
///       - {path: ~/.ssh, access: deny}
/// ```
///
/// Resolution ([CubeFsPolicy.accessFor]) is pure string math — a lexical
/// traversal guard, no filesystem access: paths are `~`-expanded (when
/// [homeDir] is known; a `~` path with unknown [homeDir] is denied), `.`
/// and `..` segments are collapsed (a path that climbs above `/` is denied),
/// and symlinks are intentionally left unresolved. Relative paths resolve
/// against the workspace (the sandbox working directory).
///
/// The **longest matching mount wins**; otherwise a path inside the
/// workspace is read/write, and anything else is denied.
///
/// Parsing is strict: any schema problem throws [ConfigException] naming the
/// YAML path.
library;

import 'package:yaml/yaml.dart';

import '../../exceptions.dart';

/// Access level granted for a path.
enum CubePathAccess {
  /// Read-only (`ro` in the cube yaml).
  readOnly('ro'),

  /// Read and write (`rw` in the cube yaml).
  readWrite('rw'),

  /// No access at all (`deny` in the cube yaml).
  deny('deny');

  const CubePathAccess(this.label);

  /// The config-file label.
  final String label;

  /// Parses [label], throwing [ConfigException] on an unknown level.
  static CubePathAccess parse(String label, String where) {
    for (final access in values) {
      if (access.label == label) return access;
    }
    throw ConfigException(
      '$where: unknown access "$label" — supported: '
      '${values.map((a) => a.label).join(', ')}',
    );
  }
}

/// One mount entry: a path prefix and the access level granted under it.
final class CubeMount {
  /// Creates a mount; [path] is kept as written (`~` expands per query).
  const CubeMount({required this.path, required this.access});

  /// The mount path prefix (absolute, or `~`-relative).
  final String path;

  /// Access granted under [path].
  final CubePathAccess access;
}

/// The `spec.filesystem:` section: workspace root plus mount overrides.
final class CubeFsPolicy {
  /// Creates a policy; [workspace] must be absolute (enforced at parse).
  const CubeFsPolicy({this.workspace = '/workspace', this.mounts = const []});

  /// The read/write root; everything outside it is denied unless a mount
  /// grants access.
  final String workspace;

  /// Mount overrides, longest prefix wins over [workspace].
  final List<CubeMount> mounts;

  /// Parses the `spec.filesystem:` section. `null` (section absent) yields
  /// the default: workspace `/workspace`, no mounts.
  factory CubeFsPolicy.fromYaml(Object? node) {
    if (node == null) return const CubeFsPolicy();
    if (node is! YamlMap) {
      throw ConfigException(
        'cube.spec.filesystem: must be a map with optional "workspace"/'
        '"mounts", got ${node.runtimeType}',
      );
    }
    for (final key in node.keys) {
      if (key is! String || (key != 'workspace' && key != 'mounts')) {
        throw ConfigException(
          'cube.spec.filesystem: unknown key "$key" — supported: workspace, '
          'mounts',
        );
      }
    }
    final workspace = node['workspace'];
    if (workspace != null &&
        (workspace is! String ||
            !workspace.startsWith('/') && !workspace.startsWith('~/') ||
            workspace.trim().isEmpty)) {
      throw ConfigException(
        'cube.spec.filesystem.workspace: must be an absolute path (or '
        '~/-relative), got $workspace',
      );
    }
    final mountsNode = node['mounts'];
    final mounts = <CubeMount>[];
    if (mountsNode != null) {
      if (mountsNode is! YamlList) {
        throw ConfigException(
          'cube.spec.filesystem.mounts: must be a list of mount maps',
        );
      }
      for (final (index, entry) in mountsNode.indexed) {
        mounts.add(_parseMount(entry, 'cube.spec.filesystem.mounts[$index]'));
      }
    }
    return CubeFsPolicy(
      workspace: workspace == null ? '/workspace' : workspace.trim(),
      mounts: List.unmodifiable(mounts),
    );
  }

  /// Access level for [path]: the longest matching mount, else read/write
  /// inside [workspace], else [CubePathAccess.deny]. `~` paths with an
  /// unknown [homeDir], and paths that traverse above `/`, are denied.
  ///
  /// Pure string math — never touches the filesystem; symlinked paths are
  /// judged by their written form (the traversal guard is lexical only).
  CubePathAccess accessFor(String path, {String? homeDir}) {
    final target = _resolve(path, homeDir: homeDir);
    if (target == null) return CubePathAccess.deny;

    CubeMount? best;
    var bestLength = -1;
    for (final mount in mounts) {
      final base = _resolve(mount.path, homeDir: homeDir);
      if (base == null) continue;
      if (_within(target, base) && base.length > bestLength) {
        best = mount;
        bestLength = base.length;
      }
    }
    if (best != null) return best.access;

    final ws = _resolve(workspace, homeDir: homeDir);
    if (ws != null && _within(target, ws)) return CubePathAccess.readWrite;
    return CubePathAccess.deny;
  }

  static CubeMount _parseMount(Object? node, String where) {
    if (node is! YamlMap) {
      throw ConfigException('$where: must be a map with "path" and "access"');
    }
    for (final key in node.keys) {
      if (key is! String || (key != 'path' && key != 'access')) {
        throw ConfigException(
          '$where: unknown key "$key" — supported: path, access',
        );
      }
    }
    final path = node['path'];
    if (path is! String || path.trim().isEmpty) {
      throw ConfigException('$where.path: must be a non-empty string');
    }
    final access = node['access'];
    if (access is! String) {
      throw ConfigException('$where.access: must be one of ro, rw, deny');
    }
    return CubeMount(
      path: path.trim(),
      access: CubePathAccess.parse(access.trim(), '$where.access'),
    );
  }

  /// Lexically resolves [raw] to a normalized absolute path, or `null` when
  /// it cannot resolve (`~` without [homeDir], or `..` above the root).
  static String? _resolve(String raw, {String? homeDir}) {
    final path = raw.trim();
    if (path.isEmpty) return null;
    final home = homeDir?.trim();
    final hasHome = home != null && home.isNotEmpty;
    String target;
    if (path == '~' || path.startsWith('~/')) {
      if (!hasHome) return null;
      target = path == '~' ? home : '$home/${path.substring(2)}';
    } else if (path.startsWith('/')) {
      target = path;
    } else {
      // Relative path: the sandbox working directory is the workspace, so
      // resolve against it (workspace is validated absolute at parse time).
      target = '/workspace/$path';
    }
    return _normalize(target);
  }

  /// Collapses `.` and `..` segments; `null` when the path escapes above `/`.
  static String? _normalize(String target) {
    final stack = <String>[];
    for (final segment in target.split('/')) {
      if (segment.isEmpty || segment == '.') continue;
      if (segment == '..') {
        if (stack.isEmpty) return null; // traversal above the root
        stack.removeLast();
      } else {
        stack.add(segment);
      }
    }
    return '/${stack.join('/')}';
  }

  /// Whether [path] equals or lives under [prefix]. The root prefix
  /// matches everything (the `$prefix/` join would spell `//` and never
  /// match, silently voiding a `{path: /, access: …}` mount).
  static bool _within(String path, String prefix) =>
      prefix == '/' || path == prefix || path.startsWith('$prefix/');
}

